#include "stdlib/stats/base/dists/gamma/quantile.h"
#include "stdlib/math/base/special/gammaincinv.h"
#include "stdlib/math/base/assert/is_nan.h"
#include <stdbool.h>

/**
* Evaluates the quantile function for a gamma distribution with shape parameter `alpha` and rate parameter `beta` at a probability `p`.
*
* @param p        input probability
* @param alpha    shape parameter
* @param beta     rate parameter
* @return         evaluated quantile function
*
* @example
* double y = stdlib_base_dists_gamma_quantile( 0.8, 2.0, 1.0 );
* // returns ~2.994
*/
double stdlib_base_dists_gamma_quantile( const double p, const double alpha, const double beta ) {
	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha < 0.0 ||
		beta <= 0.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( alpha == 0.0 ) {
		return 0.0;
	}
	return ( 1.0 / beta ) * stdlib_base_gammaincinv( p, alpha, false );
}
